-- Insert comprehensive lessons
INSERT INTO public.lessons (title, slug, description, content, difficulty_level, category, order_index, estimated_time) VALUES
-- Основы (Beginner Level)
('Введение в базы данных', 'intro-to-databases', 'Основные понятия баз данных и СУБД', '{"sections": [{"title": "Что такое база данных?", "content": "База данных - это организованная коллекция структурированной информации или данных, которые обычно хранятся в электронном виде в компьютерной системе. База данных обычно управляется системой управления базами данных (СУБД)."}, {"title": "Типы баз данных", "content": "Существует несколько типов баз данных: реляционные (SQL), документные (MongoDB), графовые (Neo4j), колоночные (Cassandra) и другие. Реляционные базы данных наиболее распространены."}, {"title": "СУБД", "content": "Система управления базами данных (СУБД) - это программное обеспечение, которое взаимодействует с пользователями, приложениями и самой базой данных для захвата и анализа данных."}]}', 1, 'Основы', 1, 45),

('Основы SQL', 'sql-basics', 'Изучение основных команд SQL', '{"sections": [{"title": "Что такое SQL?", "content": "SQL (Structured Query Language) - это стандартный язык для работы с реляционными базами данных. SQL позволяет создавать, изменять и извлекать данные из баз данных."}, {"title": "Основные команды", "content": "SELECT - выборка данных, INSERT - вставка данных, UPDATE - обновление данных, DELETE - удаление данных. Это четыре основные операции CRUD."}, {"title": "Синтаксис", "content": "SQL команды не чувствительны к регистру, но принято писать ключевые слова заглавными буквами. Каждая команда заканчивается точкой с запятой."}]}', 1, 'Основы', 2, 60),

('Структура таблиц', 'table-structure', 'Понимание структуры реляционных таблиц', '{"sections": [{"title": "Таблицы", "content": "Таблица - это основная структура данных в реляционной базе данных. Она состоит из строк (записей) и столбцов (полей)."}, {"title": "Первичные ключи", "content": "Первичный ключ - это уникальный идентификатор каждой записи в таблице. Он не может быть NULL и должен быть уникальным."}, {"title": "Типы данных", "content": "Основные типы данных: INTEGER (целые числа), VARCHAR (строки), DATE (даты), BOOLEAN (логические значения), DECIMAL (десятичные числа)."}]}', 1, 'Основы', 3, 50),

-- SELECT запросы (Intermediate Level)
('SELECT запросы', 'select-queries', 'Изучение команды SELECT для выборки данных', '{"sections": [{"title": "Синтаксис SELECT", "content": "SELECT column1, column2 FROM table_name; - базовый синтаксис для выборки данных из таблицы."}, {"title": "Выборка всех столбцов", "content": "SELECT * FROM table_name; - звездочка (*) означает выборку всех столбцов таблицы."}, {"title": "Псевдонимы", "content": "SELECT column1 AS alias1 FROM table_name; - AS позволяет задать псевдоним для столбца или таблицы."}]}', 2, 'Запросы', 4, 75),

('WHERE условия', 'where-conditions', 'Фильтрация данных с помощью WHERE', '{"sections": [{"title": "Основы WHERE", "content": "WHERE clause используется для фильтрации записей. Только записи, удовлетворяющие условию, будут включены в результат."}, {"title": "Операторы сравнения", "content": "= (равно), != или <> (не равно), > (больше), < (меньше), >= (больше или равно), <= (меньше или равно)."}, {"title": "Логические операторы", "content": "AND (и), OR (или), NOT (не). Используются для комбинирования условий."}]}', 2, 'Запросы', 5, 80),

('ORDER BY сортировка', 'order-by-sorting', 'Сортировка результатов запросов', '{"sections": [{"title": "Основы сортировки", "content": "ORDER BY используется для сортировки результатов по одному или нескольким столбцам."}, {"title": "ASC и DESC", "content": "ASC - сортировка по возрастанию (по умолчанию), DESC - сортировка по убыванию."}, {"title": "Множественная сортировка", "content": "ORDER BY column1 ASC, column2 DESC; - сортировка по нескольким столбцам."}]}', 2, 'Запросы', 6, 60),

-- Функции и агрегация (Intermediate-Advanced)
('Агрегатные функции', 'aggregate-functions', 'COUNT, SUM, AVG, MIN, MAX', '{"sections": [{"title": "COUNT", "content": "COUNT(*) - подсчет всех строк, COUNT(column) - подсчет не-NULL значений в столбце."}, {"title": "SUM и AVG", "content": "SUM() - сумма значений, AVG() - среднее арифметическое значений."}, {"title": "MIN и MAX", "content": "MIN() - минимальное значение, MAX() - максимальное значение в столбце."}]}', 3, 'Функции', 7, 90),

('GROUP BY группировка', 'group-by-grouping', 'Группировка данных для агрегации', '{"sections": [{"title": "Основы GROUP BY", "content": "GROUP BY группирует строки с одинаковыми значениями в указанных столбцах."}, {"title": "HAVING", "content": "HAVING используется для фильтрации групп, созданных GROUP BY. Аналог WHERE для групп."}, {"title": "Правила группировки", "content": "Все столбцы в SELECT (кроме агрегатных функций) должны быть в GROUP BY."}]}', 3, 'Функции', 8, 100),

-- JOIN операции (Advanced)
('INNER JOIN', 'inner-join', 'Соединение таблиц по общим полям', '{"sections": [{"title": "Что такое JOIN", "content": "JOIN используется для объединения строк из двух или более таблиц на основе связанного между ними столбца."}, {"title": "INNER JOIN", "content": "INNER JOIN возвращает записи, которые имеют совпадающие значения в обеих таблицах."}, {"title": "Синтаксис", "content": "SELECT columns FROM table1 INNER JOIN table2 ON table1.column = table2.column;"}]}', 4, 'Соединения', 9, 120),

('LEFT и RIGHT JOIN', 'left-right-join', 'Внешние соединения таблиц', '{"sections": [{"title": "LEFT JOIN", "content": "LEFT JOIN возвращает все записи из левой таблицы и совпадающие записи из правой таблицы."}, {"title": "RIGHT JOIN", "content": "RIGHT JOIN возвращает все записи из правой таблицы и совпадающие записи из левой таблицы."}, {"title": "NULL значения", "content": "Если нет совпадения, результат содержит NULL для столбцов другой таблицы."}]}', 4, 'Соединения', 10, 110),

-- Подзапросы (Advanced)
('Подзапросы', 'subqueries', 'Вложенные SELECT запросы', '{"sections": [{"title": "Что такое подзапрос", "content": "Подзапрос - это запрос, вложенный в другой запрос. Может использоваться в SELECT, WHERE, FROM."}, {"title": "Скалярные подзапросы", "content": "Подзапрос, возвращающий одно значение. Может использоваться везде, где ожидается одно значение."}, {"title": "IN и EXISTS", "content": "IN проверяет, содержится ли значение в результате подзапроса. EXISTS проверяет, возвращает ли подзапрос хотя бы одну строку."}]}', 5, 'Продвинутые', 11, 150),

-- Модификация данных
('INSERT данных', 'insert-data', 'Добавление новых записей в таблицу', '{"sections": [{"title": "Основы INSERT", "content": "INSERT INTO используется для добавления новых записей в таблицу."}, {"title": "Синтаксис", "content": "INSERT INTO table_name (column1, column2) VALUES (value1, value2);"}, {"title": "Множественная вставка", "content": "INSERT INTO table_name VALUES (value1, value2), (value3, value4);"}]}', 2, 'Модификация', 12, 70),

('UPDATE данных', 'update-data', 'Обновление существующих записей', '{"sections": [{"title": "Основы UPDATE", "content": "UPDATE используется для изменения существующих записей в таблице."}, {"title": "Синтаксис", "content": "UPDATE table_name SET column1 = value1 WHERE condition;"}, {"title": "Безопасность", "content": "Всегда используйте WHERE с UPDATE, иначе обновятся все записи!"}]}', 2, 'Модификация', 13, 65),

('DELETE данных', 'delete-data', 'Удаление записей из таблицы', '{"sections": [{"title": "Основы DELETE", "content": "DELETE используется для удаления записей из таблицы."}, {"title": "Синтаксис", "content": "DELETE FROM table_name WHERE condition;"}, {"title": "Осторожность", "content": "DELETE без WHERE удалит все записи! Всегда проверяйте условие."}]}', 2, 'Модификация', 14, 60),

-- Создание структур
('CREATE TABLE', 'create-table', 'Создание новых таблиц', '{"sections": [{"title": "Основы CREATE TABLE", "content": "CREATE TABLE используется для создания новой таблицы в базе данных."}, {"title": "Определение столбцов", "content": "CREATE TABLE table_name (column1 datatype, column2 datatype);"}, {"title": "Ограничения", "content": "PRIMARY KEY, FOREIGN KEY, NOT NULL, UNIQUE, CHECK - основные ограничения."}]}', 3, 'DDL', 15, 100);

