((SELECT id FROM public.lessons WHERE slug = 'intro-to-databases'), 'Типы баз данных', 'Какой тип базы данных использует SQL?', 'Какой тип базы данных использует язык SQL?', 'Реляционная', '["SQL означает Structured Query Language", "Реляционные БД используют таблицы"]', 1, 10, 2),
((SELECT id FROM public.lessons WHERE slug = 'intro-to-databases'), 'СУБД', 'Что означает аббревиатура СУБД?', 'Расшифруйте СУБД:', 'Система управления базами данных', '["СУБД управляет базой данных", "Это программное обеспечение"]', 1, 10, 3),
((SELECT id FROM public.lessons WHERE slug = 'intro-to-databases'), 'Примеры СУБД', 'Назовите популярную СУБД', 'Какая из перечисленных является СУБД: Word, MySQL, Excel?', 'MySQL', '["MySQL - это система управления БД", "Word и Excel не являются СУБД"]', 1, 10, 4),
((SELECT id FROM public.lessons WHERE slug = 'intro-to-databases'), 'Структура данных', 'Как организованы данные в реляционной БД?', 'В каком виде хранятся данные в реляционной базе данных?', 'В таблицах', '["Реляционные БД используют табличную структуру", "Таблицы состоят из строк и столбцов"]', 1, 10, 5);

