((SELECT id FROM public.lessons WHERE slug = 'sql-basics'), 'Основные команды', 'Какая команда используется для выборки данных?', 'Какая SQL команда используется для выборки данных из таблицы?', 'SELECT', '["Эта команда начинается с S", "Используется для получения данных"]', 1, 10, 2),
((SELECT id FROM public.lessons WHERE slug = 'sql-basics'), 'CRUD операции', 'Что означает CRUD?', 'Что означает аббревиатура CRUD в контексте баз данных?', 'Create Read Update Delete', '["Это основные операции с данными", "C-создание, R-чтение, U-обновление, D-удаление"]', 1, 15, 3),
((SELECT id FROM public.lessons WHERE slug = 'sql-basics'), 'Команда вставки', 'Какая команда добавляет данные?', 'Какая SQL команда используется для добавления новых данных в таблицу?', 'INSERT', '["Эта команда добавляет новые записи", "Начинается с I"]', 1, 10, 4),
((SELECT id FROM public.lessons WHERE slug = 'sql-basics'), 'Команда обновления', 'Какая команда изменяет данные?', 'Какая SQL команда используется для изменения существующих данных?', 'UPDATE', '["Эта команда изменяет существующие записи", "Начинается с U"]', 1, 10, 5),
((SELECT id FROM public.lessons WHERE slug = 'sql-basics'), 'Команда удаления', 'Какая команда удаляет данные?', 'Какая SQL команда используется для удаления данных из таблицы?', 'DELETE', '["Эта команда удаляет записи", "Начинается с D"]', 1, 10, 6),
((SELECT id FROM public.lessons WHERE slug = 'sql-basics'), 'Регистр команд', 'Чувствителен ли SQL к регистру?', 'Чувствительны ли SQL команды к регистру букв?', 'Нет', '["SQL команды можно писать любым регистром", "SELECT = select = Select"]', 1, 10, 7),
((SELECT id FROM public.lessons WHERE slug = 'sql-basics'), 'Окончание команд', 'Чем заканчивается SQL команда?', 'Каким символом должна заканчиваться SQL команда?', 'Точкой с запятой', '["Этот символ ставится в конце предложения", "Символ ;"]', 1, 10, 8);

-- Exercises for "SELECT запросы"
INSERT INTO public.exercises (lesson_id, title, description, question, correct_answer, hints, difficulty_level, points, order_index) VALUES
((SELECT id FROM public.lessons WHERE slug = 'select-queries'), 'Простой SELECT', 'Напишите запрос для выборки всех данных из таблицы users', 'Выберите все данные из таблицы users:', 'SELECT * FROM users;', '["Используйте * для выбора всех колонок", "Не забудьте точку с запятой"]', 2, 15, 1),
((SELECT id FROM public.lessons WHERE slug = 'select-queries'), 'Выборка столбцов', 'Выберите только имя и возраст из таблицы users', 'Напишите запрос для выборки столбцов name и age из таблицы users:', 'SELECT name, age FROM users;', '["Перечислите столбцы через запятую", "SELECT column1, column2 FROM table"]', 2, 15, 2),
((SELECT id FROM public.lessons WHERE slug = 'select-queries'), 'Псевдонимы столбцов', 'Используйте псевдоним для столбца name', 'Выберите столбец name с псевдонимом full_name из таблицы users:', 'SELECT name AS full_name FROM users;', '["Используйте ключевое слово AS", "AS создает псевдоним"]', 2, 20, 3),
((SELECT id FROM public.lessons WHERE slug = 'select-queries'), 'Псевдонимы таблиц', 'Используйте псевдоним для таблицы', 'Выберите все данные из таблицы users, используя псевдоним u:', 'SELECT * FROM users AS u;', '["Псевдоним ставится после имени таблицы", "FROM table AS alias"]', 2, 20, 4),
((SELECT id FROM public.lessons WHERE slug = 'select-queries'), 'Выборка уникальных значений', 'Выберите уникальные значения столбца city', 'Напишите запрос для выборки уникальных значений из столбца city таблицы users:', 'SELECT DISTINCT city FROM users;', '["Используйте ключевое слово DISTINCT", "DISTINCT убирает дубликаты"]', 2, 25, 5);

