-- Exercises for "WHERE условия"
INSERT INTO public.exercises (lesson_id, title, description, question, correct_answer, hints, difficulty_level, points, order_index) VALUES
((SELECT id FROM public.lessons WHERE slug = 'where-conditions'), 'Простое условие WHERE', 'Выберите пользователей старше 25 лет', 'Напишите запрос для выборки пользователей из таблицы users, где age больше 25:', 'SELECT * FROM users WHERE age > 25;', '["Используйте оператор >", "WHERE age > 25"]', 2, 15, 1),
((SELECT id FROM public.lessons WHERE slug = 'where-conditions'), 'Условие равенства', 'Выберите пользователя с именем John', 'Выберите всех пользователей с именем John из таблицы users:', 'SELECT * FROM users WHERE name = ''John'';', '["Используйте оператор =", "Строки заключаются в кавычки"]', 2, 15, 2),
((SELECT id FROM public.lessons WHERE slug = 'where-conditions'), 'Логический оператор AND', 'Выберите пользователей старше 25 и из города Moscow', 'Выберите пользователей старше 25 лет из города Moscow:', 'SELECT * FROM users WHERE age > 25 AND city = ''Moscow'';', '["Используйте AND для объединения условий", "Оба условия должны быть истинными"]', 2, 20, 3),
((SELECT id FROM public.lessons WHERE slug = 'where-conditions'), 'Логический оператор OR', 'Выберите пользователей из Moscow или SPb', 'Выберите пользователей из городов Moscow или SPb:', 'SELECT * FROM users WHERE city = ''Moscow'' OR city = ''SPb'';', '["Используйте OR", "Достаточно одного истинного условия"]', 2, 20, 4),
((SELECT id FROM public.lessons WHERE slug = 'where-conditions'), 'Оператор IN', 'Используйте IN для выбора из нескольких городов', 'Выберите пользователей из городов Moscow, SPb, Kazan используя IN:', 'SELECT * FROM users WHERE city IN (''Moscow'', ''SPb'', ''Kazan'');', '["IN проверяет вхождение в список", "Список в скобках через запятую"]', 2, 25, 5),
((SELECT id FROM public.lessons WHERE slug = 'where-conditions'), 'Оператор BETWEEN', 'Выберите пользователей в возрасте от 20 до 30 лет', 'Используйте BETWEEN для выбора пользователей от 20 до 30 лет:', 'SELECT * FROM users WHERE age BETWEEN 20 AND 30;', '["BETWEEN включает граничные значения", "BETWEEN value1 AND value2"]', 2, 25, 6),
((SELECT id FROM public.lessons WHERE slug = 'where-conditions'), 'Оператор LIKE', 'Найдите пользователей, чье имя начинается с J', 'Используйте LIKE для поиска имен, начинающихся с J:', 'SELECT * FROM users WHERE name LIKE ''J%'';', '["% означает любые символы", "LIKE используется для поиска по шаблону"]', 2, 25, 7),
((SELECT id FROM public.lessons WHERE slug = 'where-conditions'), 'Проверка на NULL', 'Найдите пользователей без указанного email', 'Выберите пользователей, у которых email равен NULL:', 'SELECT * FROM users WHERE email IS NULL;', '["Используйте IS NULL", "Нельзя использовать = NULL"]', 2, 20, 8);

